                <div class="question-box" id="box-${index}">
                    <div class="question-title">${index + 1}. ${q.question}</div>
                    <ul class="options-list">
                        ${optionsHtml}
                    </ul>
                    <div class="feedback-msg"></div>
                </div>
            `;
        });
        container.innerHTML = htmlContent;
