        questions.forEach((q, index) => {
            const selectedOption = document.querySelector(`input[name="question${index}"]:checked`);
            const feedbackBox = document.querySelector(`#box-${index} .feedback-msg`);

            if (selectedOption) {
                const userAnswer = parseInt(selectedOption.value);
                answeredQuestions.push({ q: index, user: userAnswer, correct: q.correct });

                // Lógica de visualização de acerto/erro
                const parentLabel = document.querySelector(`label[for="question${index}_${userAnswer}"]`);

                if (userAnswer === q.correct) {
                    score++;
